-- Backfill del detalle estructurado (ficha_detail) para las fichas ya
-- generadas: cobre (Sonora), antimonio (Honduras) y REE (TRENTO). Mueve el
-- contenido que antes estaba hardcodeado en el renderer hacia la base.
-- Idempotente (UPDATE por referencia del requerimiento).

-- Cátodos de cobre · Sonora
UPDATE public.sourcing_submissions s
  SET ficha_detail = '{"intro":"Detalle del mineral ofertado — Cátodos de cobre refinado. Datos tomados de la disponibilidad informada por el proveedor. Precio referenciado al valor LME con descuento; sujeto a due diligence e inspección independiente.","tables":[{"title":"Detalle del mineral ofertado","columns":["Característica","Detalle"],"rows":[["Producto","Cátodos de cobre refinado"],["Origen","Estado de Sonora, México"],["Pureza mínima","99,99% Cu"],["Formato","Placas planas de aprox. 1,00 m × 0,80 m"],["Espesor","5 mm a 10 mm"],["Stock disponible","300 toneladas"],["Capacidad de suministro","250 toneladas por semana"],["Primera operación spot","80 toneladas"],["Aplicaciones","Conductores eléctricos, cables, componentes eléctricos y usos industriales"]]},{"title":"Condiciones comerciales","columns":["Concepto comercial","Condición"],"rows":[["Precio","Referenciado al valor LME, con descuento de 5%"],["Modo de pago","Contado por transferencia electrónica al momento de la carga y recepción de la mercancía"],["Primera operación (spot)","80 toneladas"],["Esquema","Operación formal con cumplimiento fiscal en México"]]}],"clauses":["Posibilidad de coordinar visita técnica, inspección y toma de muestras. Para autorizar la visita se requiere identificación de los asistentes y Orden de Compra (OC).","Posterior al análisis de muestras se formaliza el contrato y se programa la fecha de compra y carga.","Precio referenciado al valor LME con descuento de 5%; puede ajustarse ante variación de la bolsa internacional del cobre.","Operación bajo esquema formal y cumplimiento fiscal en México. Documento de referencia comercial — no constituye oferta vinculante."]}'::jsonb, updated_at = now()
  FROM public.sourcing_requests r
  WHERE s.request_id = r.id AND (r.reference ILIKE 'SRC-CU-CATODO-SONORA%');

-- Antimonio en breña · Honduras (Corp. Minera A&D)
UPDATE public.sourcing_submissions s
  SET ficha_detail = '{"intro":"Detalle del mineral ofertado — Antimonio (Sb) en breña. Datos tomados de la Soft Corporate Offer (SCO) del proveedor. Precio en USD por tonelada métrica, con impuestos, escalonado por ley de antimonio; ante variación de la bolsa internacional se ajusta de manera proporcional.","tables":[{"title":"Detalle del mineral ofertado","columns":["Característica","Detalle"],"rows":[["Producto","Antimonio (Sb) en breña — mineral triturado"],["Origen","Honduras"],["Granulometría","1 pulgada a finos"],["Ley (rango)","35% a 77% Sb"],["Presentación","Breña / mineral a granel"],["Disponibilidad","100 t/mes (a más)"],["Período de contrato","1 año (12 meses), a más"],["Modalidad","FOB"],["Puertos de embarque","Puerto Cortés (Cortés) · Puerto Castilla (Colón) · San Lorenzo (Choluteca)"]]},{"title":"Tabla de leyes y precios (US$/MT, con impuestos)","columns":["Ley % Sb","Precio/MT","Ley % Sb","Precio/MT"],"rows":[["35%","US$ 5.616","57%","US$ 6.336"],["36%","US$ 5.649","58%","US$ 6.368"],["37%","US$ 5.683","59%","US$ 6.401"],["38%","US$ 5.717","60%","US$ 6.433"],["39%","US$ 5.750","61%","US$ 6.465"],["40%","US$ 5.784","62%","US$ 6.498"],["41%","US$ 5.816","63%","US$ 6.530"],["42%","US$ 5.849","64%","US$ 6.563"],["43%","US$ 5.881","65%","US$ 6.595"],["44%","US$ 5.914","66%","US$ 6.628"],["45%","US$ 5.946","67%","US$ 6.660"],["46%","US$ 5.979","68%","US$ 6.693"],["47%","US$ 6.011","69%","US$ 6.725"],["48%","US$ 6.044","70%","US$ 6.757"],["49%","US$ 6.076","71%","US$ 6.790"],["50%","US$ 6.108","72%","US$ 6.822"],["51%","US$ 6.141","73%","US$ 6.855"],["52%","US$ 6.173","74%","US$ 6.888"],["53%","US$ 6.206","75%","US$ 6.920"],["54%","US$ 6.238","76%","US$ 6.952"],["55%","US$ 6.271","77%","US$ 7.030"],["56%","US$ 6.303","",""]]}],"clauses":["Precios en dólares americanos por tonelada métrica (MT), con impuestos; ajustables proporcionalmente ante variación de la bolsa internacional de antimonio.","Modalidad FOB en los puertos indicados. El proveedor declara ser titular de las concesiones mineras.","Pago mediante SBLC 100% irrevocable, transferible y divisible, con pago en el puerto de carga tras informes de inspección y documentos de embarque vía SWIFT MT103. Banca: Bank of America (intermediario), Banco FICOHSA (beneficiario), beneficiario final Corporación Minera A&D, S.A. de C.V.","Oferta dirigida solo a compradores directos que acrediten prueba de fondos (POF). Documento de referencia comercial — no constituye oferta vinculante."]}'::jsonb, updated_at = now()
